endpoint.request:
{
  name, code, description, category_id, is_active,            // invariati (0403/0410)
  sections: [ { id: number|null, name: string(1..255), description: string|null } ],  // ordine = array; max 20; nomi unici (case-insensitive)
  items: [ {
    id, name, description, is_required, allowed_file_types, max_file_size_kb,
    min_files, max_files, validation_prompt, max_age_days,     // invariati
    section_index: number|null,                                // indice in `sections`; null = nessun gruppo
    date_field: string|null                                    // max 64, ^[a-z][a-z0-9_]*$, ammesso solo con max_age_days
  } ]                                                          // il campo `section` (testo) non esiste più
}

endpoint.response:
data: { ...DocumentChecklist 0410,
        sections: [ { id: number, name: string, description: string|null } ],   // ordinati per position
        items: [ { ...item 0403 senza `section`, section_index: number|null, date_field: string|null } ] }
